/**
 * Golden tests (docs/adr/0006-adopt-pybricks-mpy-cross.md): the WebAssembly compiler MatPilot
 * ships must produce byte-for-byte the same .mpy files as pybricksdev's compiler (PyPI
 * mpy-cross-v6, generated by scripts/golden/generate-mpy-cross-v6.sh).
 */
import { createHash } from 'node:crypto';
import { readdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { compilePython } from './compiler';

const DIR = fileURLToPath(new URL('./__golden__/mpy-cross-v6/', import.meta.url));
const read = (name: string) => readFileSync(`${DIR}${name}`);
const manifest = JSON.parse(read('manifest.json').toString()) as {
  version: string;
  outputs: Record<string, string>;
};
const sources = readdirSync(DIR)
  .filter((name) => name.endsWith('.py'))
  .sort();

describe('golden files', () => {
  it('match the manifest written by the generator', () => {
    for (const [name, sha256] of Object.entries(manifest.outputs)) {
      expect(createHash('sha256').update(read(name)).digest('hex'), name).toBe(sha256);
    }
    expect(manifest.version).toBe('1.1.2');
  });
});

describe('@pybricks/mpy-cross-v6 matches pybricksdev', () => {
  // The package's Emscripten loader (2022) prefers fetch() whenever it exists, which in Node 18+
  // cannot read a file path. Without fetch it reads the .wasm from disk. Browsers keep fetch.
  beforeEach(() => {
    vi.stubGlobal('fetch', undefined);
  });

  it.each(sources)('%s', async (source) => {
    const outcome = await compilePython(read(source).toString('utf-8'), { sourceName: source });
    const base = source.slice(0, -'.py'.length);
    if (`${base}.mpy` in manifest.outputs) {
      expect(outcome.ok, outcome.ok ? '' : outcome.error.detail).toBe(true);
      if (outcome.ok) expect(Buffer.from(outcome.mpy).equals(read(`${base}.mpy`))).toBe(true);
    } else {
      // pybricksdev's compiler failed on this source: ours must fail the same way.
      const expected = read(`${base}.err`).toString().trim().split('\n');
      expect(outcome.ok).toBe(false);
      if (!outcome.ok) {
        expect(outcome.error.message).toBe(expected.at(-1)?.trim());
        expect(outcome.error.line).toBe(Number(/line (\d+)/.exec(expected.join('\n'))?.[1]));
      }
    }
  });
});
